use super::*;
use crate::money::{scale, Money, Rounding};

/// What a whole year of carrying today's debt costs, if nothing is paid down. Often the number that
/// changes somebody's mind, so it is given rather than left as an exercise.
pub fn annual_interest_cost(p: &Position) -> Money {
    scale(p.daily_interest, 365.0, Rounding::HalfUp)
}
